 path=ROOT/"data/drafts/specs/토목/6-3-4.json";pkg=json.loads(path.read_text(encoding="utf8"));key=pkg["draft"]["id"]; chunks_path=ROOT/"data/processed/chunks.all.jsonl"; v=validate_one(path,ROOT/"data/drafts",load_chunks(chunks_path),file_sha256(chunks_path));assert not v["format_issues"] and not v["citation_issues"],v
