 specs=sorted((ROOT/"data/drafts/specs").rglob("*.json"));ev["hashes"]["spec_manifest_sha256"]=hashlib.sha256(b"\n".join(p.relative_to(ROOT/"data/drafts/specs").as_posix().encode()+b"\0"+sha(p).encode() for p in specs)).hexdigest();ev["hashes"]["chunks_sha256"]=sha(chunks_path);ev["hashes"]["executable_sha256"]=sha(idxp);ev["hashes"]["runtime_per_unit_sha256"]=sha(ROOT/"backend/agent/tools/calc/per_unit.py");ev["remaining_failures"]={"calculator_or_rule_gate":sum(x["stage"]=="calculator_execution_or_rule_gate" for x in idx["failed"]),"source_preflight":sum(x["stage"]=="source_preflight" for x in idx["failed"]),"format_preflight":sum(x["stage"]=="format_or_input_preflight" for x in idx["failed"]),"open_policy":"cooling-tower unit basis inferred as 인/대; maintenance 2-1-6 roller count and unresolved rates/combination policies remain open"};evp.write_text(json.dumps(ev,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
 print(json.dumps({"promoted":key,"active":{"executable":len(idx["executable"]),"failed":len(idx["failed"]),"unsupported":174,"excluded":2,"stages":ev["current_active_lists"]["failure_stages"]},"full_rule_verification":0,"runtime_sha256":ev["hashes"]["runtime_per_unit_sha256"]},ensure_ascii=False,indent=2))
